export interface Subscriber {
  id: string;
  name: string;
  email: string;
  topics: string[];
}

export const createSubscriber = (overrides: Partial<Subscriber> = {}): Subscriber => ({
  id: "subscriber-1",
  name: "Test Subscriber",
  email: "subscriber@example.com",
  topics: ["product"],
  ...overrides,
});
---MSW---
import { setupServer } from "msw/node";
import type { RequestHandler } from "msw";

// Creates an MSW server and wires the standard lifecycle hooks.
// Call once per test file; add per-test overrides with server.use(...).
export function startApiServer(...handlers: RequestHandler[]) {
  const server = setupServer(...handlers);

  beforeAll(() => server.listen({ onUnhandledRequest: "error" }));
  afterEach(() => server.resetHandlers());
  afterAll(() => server.close());

  return server;
}
---SETUP---
import "@testing-library/jest-dom/vitest";
---CLIENT---
export interface ApiRequest {
  method: string;
  params: Record<string, unknown>;
}

export async function postApi(method: string, params: Record<string, unknown>): Promise<unknown> {
  const response = await fetch("/api", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ method, params } satisfies ApiRequest),
  });
  return response.json();
}
